// Package testdb provides grants for disposable integration-test roles.
package testdb

// RuntimeGrants accepts a role identifier generated by the test fixture.
func RuntimeGrants(role string) string {
	return `GRANT USAGE ON SCHEMA favorites TO ` + role + `;
 GRANT SELECT, INSERT, UPDATE ON favorites.owners, favorites.activity_buckets, favorites.outbox TO ` + role + `;
 GRANT SELECT, INSERT, UPDATE, DELETE ON favorites.folders, favorites.items TO ` + role + `;
 GRANT SELECT, INSERT, DELETE ON favorites.requests TO ` + role + `;
 GRANT SELECT, INSERT ON favorites.events, favorites.activity_history TO ` + role + `;
 GRANT SELECT ON favorites.activity_retention TO ` + role + `;
 GRANT USAGE ON ALL SEQUENCES IN SCHEMA favorites TO ` + role
}
